import type { SessionSummary } from './types';

export function sessionMatchesQuery(
  s: SessionSummary,
  query: string,
): boolean {
  const q = query.trim().toLowerCase();
  if (q === '') return true;
  const started = s.started_at
    ? `${s.started_at} ${new Date(s.started_at).toLocaleString()}`
    : '';
  return `${s.id} ${s.file} ${started}`.toLowerCase().includes(q);
}

import { describe, expect, it } from 'vitest';
import { sessionMatchesQuery } from './session-filter';
import type { SessionSummary } from './types';

function session(overrides: Partial<SessionSummary> = {}): SessionSummary {
  return {
    id: '2026-11-05-standup-0930',
    file: '2026-11-05-standup-0930.md',
    started_at: '2026-11-05T09:30:00.000Z',
    ended_at: '2026-11-05T10:00:00.000Z',
    source_lang: 'en',
    target_lang: 'vi',
    stt_provider: 'deepgram',
    model: 'nova-3',
    diarization: true,
    audio_file: null,
    speakers: {},
    duration_s: 1800,
    segments: 42,
    ...overrides,
  };
}

describe('sessionMatchesQuery', () => {
  it('matches every session on an empty or whitespace query', () => {
    expect(sessionMatchesQuery(session(), '')).toBe(true);
    expect(sessionMatchesQuery(session(), '   ')).toBe(true);
  });

  it('matches the session id case-insensitively', () => {
    expect(sessionMatchesQuery(session(), 'STANDUP')).toBe(true);
    expect(sessionMatchesQuery(session(), 'retrospective')).toBe(false);
  });

  it('matches the raw ISO date and the localized date string', () => {
    const s = session();
    expect(sessionMatchesQuery(s, '2026-11-05')).toBe(true);
    const localized = new Date(s.started_at!).toLocaleString();
    for (const part of localized.split(/[\s,/:]+/).filter(Boolean)) {
      expect(sessionMatchesQuery(s, part)).toBe(true);
    }
  });

  it('ignores leading and trailing whitespace in the query', () => {
    expect(sessionMatchesQuery(session(), '  standup  ')).toBe(true);
  });

  it('matches a session with no start date by id only', () => {
    const s = session({ started_at: null });
    expect(sessionMatchesQuery(s, 'standup')).toBe(true);
    expect(sessionMatchesQuery(s, '2026')).toBe(false);
  });
});

